class Solution:
    def maximumStrongPairXor(self, nums: List[int]) -> int:
        max_xor = 0
        n = len(nums)
        for i in range(n):
            for j in range(n):
                a = nums[i]
                b = nums[j]
                if max(a, b) <= 2 * min(a, b):
                    current_xor = a ^ b
                    if current_xor > max_xor:
                        max_xor = current_xor
        return max_xor
```

